"""Test helpers: in-process campaign runner plus a brute-force plan oracle."""
import itertools, sys
sys.path.insert(0,'/workspace/submission')
import campaign
from common import CaptureError, Invalid

def run(job):
    saved=sys.stdout
    sys.stdout=sys.stderr
    try:
        return campaign.audit(job)
    except CaptureError:
        return {'error':'capture'}
    except (Invalid,ValueError,TypeError,KeyError,IndexError,RecursionError):
        return {'error':'invalid'}
    finally:
        sys.stdout=saved

def quota(nodes):
    return [{'id':n[0],'parent':n[1],'capacity':n[2]} for n in nodes]

# ---------------------------------------------------------------- plan oracle
def _info(job,active):
    import ipaddress
    request_info={}
    for row in job['requests']:
        lease=[l for l in job['leases'] if l['id']==row['lease']][0]
        request_info[row['id']]={'at':row['at'],'service':row['service'],
                                 'group':row['group'],
                                 'address':int(ipaddress.IPv6Address(row['target'])),
                                 'end':lease['end']}
    offer_info={}
    for row in job['offers']:
        net=ipaddress.IPv6Network(row['prefix'])
        offer_info[row['id']]={'time':row['time'],'service':row['service'],
                               'lo':int(net.network_address),
                               'hi':int(net.broadcast_address),
                               'capacity':row['capacity'],'cost':row['cost'],
                               'reqs':set(row['requests'])}
    pairs=[(rid,row['id']) for row in job['offers'] for rid in row['requests']
           if active.get(rid)]
    return request_info,offer_info,pairs

def _quota_consumed(choice, nodes, info):
    node={n[0]:n for n in nodes}
    caps={n[0]:n[2] for n in nodes}
    total={n[0]:0 for n in nodes}
    for rid,_ in choice:
        at=info[rid]['group']
        while at is not None:
            total[at]=total.get(at,0)+1
            at=node[at][1]
    for name,value in total.items():
        if value>caps[name]:
            return False
    return True

def feasible(choice, request_info, offer_info, rnodes, onodes):
    used=set()
    counts={}
    for rid,oid in choice:
        if rid in used: return False
        used.add(rid)
        info=request_info[rid]; offer=offer_info[oid]
        if rid not in offer['reqs']: return False
        if offer['service']!=info['service']: return False
        if not (info['at']<=offer['time']<info['end']): return False
        if not (offer['lo']<=info['address']<=offer['hi']): return False
        counts[oid]=counts.get(oid,0)+1
    for oid,n in counts.items():
        if n>offer_info[oid]['capacity']: return False
    return (_quota_consumed(choice,rnodes,request_info)
            and _quota_consumed(choice,onodes,offer_info))

def oracle(job, active):
    """Brute force optimum (cardinality, cost) for a tiny campaign."""
    request_info,offer_info,pairs=_info(job,active)
    best=(0,0)
    for size in range(len(pairs),-1,-1):
        found=None
        for choice in itertools.combinations(pairs,size):
            if not feasible(choice,request_info,offer_info,
                            job['request_quotas'],job['offer_quotas']):
                continue
            cost=sum(offer_info[oid]['cost'] for _,oid in choice)
            if found is None or cost<found:
                found=cost
        if found is not None:
            return (size,found)
    return (0,0)

def check_plan(job, result, active):
    """Validate the returned plan against the brute-force oracle."""
    request_info,offer_info,_=_info(job,active)
    assert set(result)=={'resolved','cost','assignments'}, result
    assignments=result['assignments']
    rids=[a['request'] for a in assignments]
    assert rids==sorted(rids), 'assignments not sorted'
    assert len(set(rids))==len(rids), 'duplicate request assignment'
    choice=[(a['request'],a['offer']) for a in assignments]
    assert feasible(choice,request_info,offer_info,job['request_quotas'],
                    job['offer_quotas']), 'infeasible plan: '+repr(choice)
    cost=sum(offer_info[oid]['cost'] for _,oid in choice)
    assert cost==result['cost'], (cost,result['cost'])
    assert result['resolved']==len(assignments)
    want=oracle(job,active)
    assert (result['resolved'],result['cost'])==want, \
        ((result['resolved'],result['cost']),want)
    import base64
    kinds={s['id']:s['kind'] for s in job['services']}
    for a in assignments:
        kind=kinds[offer_info[a['offer']]['service']]
        send=[base64.b64decode(x) for x in a['send']]
        finish=[base64.b64decode(x) for x in a['finish']]
        if kind=='tcp':
            assert send==[] and finish==[], (kind,send,finish)
        elif kind=='adb':
            assert len(send)==1 and len(finish)==1, (kind,send,finish)
            from protocols import send_connect, send_close, checksum
            import struct
            body=b'host::zgrab2'
            assert send[0]==struct.pack('<6I',0x4e584e43,0x01000000,4096,len(body),
                                        checksum(body),0x4e584e43^0xffffffff)+body
            assert finish[0]==struct.pack('<6I',0x45534c43,0,0,0,0,
                                          0x45534c43^0xffffffff)
        else:
            assert len(send)==2 and finish==[], (kind,send,finish)
            from protocols import parse_sync
            sig=parse_sync(b''.join(send))
            assert sig==('sync','x','y') or sig[0]=='sync'
    return True
